solutionCode:
fun parseMotorSpeed(text: String): Double {
    return try {
        text.toDouble()
    } catch (e: NumberFormatException) {
        0.0
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testValidSpeed() {
        Assert.assertEquals(0.75, parseMotorSpeed("0.75"), 0.001)
    }

    @Test
    fun testInvalidText() {
        Assert.assertEquals(0.0, parseMotorSpeed("bad"), 0.001)
    }

    @Test
    fun testNegativeSpeed() {
        Assert.assertEquals(-0.5, parseMotorSpeed("-0.5"), 0.001)
    }

    @Test
    fun testFullSpeed() {
        Assert.assertEquals(1.0, parseMotorSpeed("1.0"), 0.001)
    }

    @Test
    fun testEmptyString() {
        Assert.assertEquals(0.0, parseMotorSpeed(""), 0.001)
    }
}
